/* Offline support for the installed web app. Generated by tools/build-deploy.sh, do not edit sw.js. */
const CACHE = 'tetbreak-93b1379b85';
const FILES = ["./", "index.html", "app.js", "game-core.js", "manifest.webmanifest", "icons/apple-touch-icon.png", "icons/icon-192.png", "icons/icon-512.png"];

// Cache all game files. cache: 'reload' skips the browser's HTTP cache, so a new version is really new.
self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE)
    .then(c => c.addAll(FILES.map(f => new Request(f, { cache: 'reload' }))))
    .then(() => self.skipWaiting()));
});

// Drop caches of older versions. A running game keeps its loaded files; the next start uses the new ones.
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k.startsWith('tetbreak-') && k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

// Cache first (instant start, works offline), network as the fallback.
self.addEventListener('fetch', e => {
  if (e.request.method !== 'GET' || new URL(e.request.url).origin !== location.origin) return;
  e.respondWith(caches.match(e.request, { ignoreSearch: true }).then(hit => hit || fetch(e.request)));
});
